// Loads the JSON emitted by scripts/build-content.mjs.
//
// The Markdown in ai-roadmaps/ is the single source of truth. These JSON files
// are build artifacts, regenerated by `node scripts/build-content.mjs` and
// git-ignored, so a fresh clone must run the build before `npm run dev`.
//
// ---------------------------------------------------------------------------
// TWO PROJECTIONS OF THE SAME DATA, LOADED DIFFERENTLY
// ---------------------------------------------------------------------------
// The build emits the curriculum twice, from one parse:
//
//   generated/index.json          ~72 KB   every phase's title, duration, goal
//                                          and the IDS of its checklist/tasks/quiz
//   generated/<track>.json        ~1300 KB every phase in full: tools, resources,
//                                          practice text, quiz questions + answers,
//                                          free-vs-paid prose
//   generated/lessons/<phase>.json        the lesson body for one phase
//
// The shell and the dashboard need the first and almost none of the second — a
// phase card renders a title, a duration, a goal and a count. Loading the full
// track files to draw that dashboard pulled all 1.3 MB into the initial bundle
// and pushed the entry chunk to 1.56 MB, which is a real cost on the connection
// this curriculum is written for.
//
// So index.json is imported EAGERLY (it is small enough to belong in the entry
// chunk) and the full track files are loaded LAZILY, per track, only when a
// reader actually opens a phase. The lesson bodies were already lazy; this makes
// the phase metadata lazy on the same principle.
//
// The light index carries checklist/task/quiz IDS rather than their text
// specifically so that progress can be counted on the dashboard without loading
// a single phase. The full text arrives when the phase does.
//
// ---------------------------------------------------------------------------
// WHY THERE IS A QUIZ ADAPTER IN THIS FILE
// ---------------------------------------------------------------------------
// The components ported from the sibling CS Roadmap project were written against
// a slightly different quiz shape than this curriculum emits:
//
//   CS Roadmap:  options: [{ text, correct: boolean }, ...]  + explanation
//   Ours:        options: ["...", "..."]                     + answerIndex + why
//
// Everything ELSE matches exactly — tasks, checklist, tools, resources and
// freeVsPaid are field-for-field identical, and the lesson files share the same
// { id, title, blocks, toc } shape.
//
// The quiz difference could be absorbed in three places: in build-content.mjs
// (changes the artifact), in Quiz.jsx and lib/quiz.js (two files, and lib/quiz.js
// is a tested pure module whose logic reads `options[].correct`), or here.
//
// Here is the right place. One function, applied once as data is loaded, keeps
// every ported component and the tested quiz module byte-for-byte identical to
// their originals — so a future diff against the sibling project stays clean and
// any upstream fix can be copied across without re-resolving a fork. Adapting at
// the data boundary is also the Phase 2 principle this curriculum teaches about
// tool results: normalise at the edge, keep the interior in one shape.

import index from "./generated/index.json";

/** Track metadata and light phase records, in curriculum order. */
export const tracks = index.tracks.map((t) => ({
  id: t.id,
  label: t.label,
  short: t.short || t.label,
  note: t.note || t.blurb,
  blurb: t.blurb,
  phaseCount: t.phases.length,
  phases: t.phases,
}));

export function findTrack(id) {
  return tracks.find((t) => t.id === id) || null;
}

/**
 * Normalise one quiz question to the shape the ported components expect.
 *
 * Our authoring shape carries `answerIndex` (a number) and `why` (prose). The
 * components expect `options` to be objects carrying a `correct` flag, and the
 * explanation under `explanation`.
 *
 * `answerIndex` is the only source of truth for correctness here. The option
 * TEXT is never inspected: a phase whose distractor happened to contain the
 * word "correct" would otherwise be able to mark itself right. lib/quiz.js
 * reads `o.correct === true` strictly for the same reason.
 *
 * A malformed question (missing or out-of-range answerIndex) yields options that
 * are all incorrect, so the reader sees the explanation without being told a
 * wrong answer was right. That is the quiet failure lib/quiz.js's header warns
 * about, and failing toward "no answer is marked correct" is the safe direction:
 * a quiz that silently marks a distractor correct teaches something false.
 */
export function normaliseQuestion(q) {
  const answerIndex = typeof q.answerIndex === "number" ? q.answerIndex : -1;

  return {
    id: q.id,
    question: q.question,
    energy: q.energy,
    options: (q.options || []).map((text, i) => ({
      text,
      correct: i === answerIndex,
    })),
    explanation: q.why || "",
  };
}

/** Normalise a whole phase: quiz questions, and nothing else needs it. */
export function normalisePhase(phase) {
  return {
    ...phase,
    quiz: (phase.quiz || []).map(normaliseQuestion),
  };
}

// Vite needs a literal glob to know what to bundle. `eager: false` (the default)
// makes each entry a dynamic import, so a track is fetched only when asked for.
const TRACK_MODULES = import.meta.glob("./generated/*.json");

// The glob above also matches index.json, search.json, shared.json and
// tracks.json. They are not track files and must not be treated as such.
const NOT_A_TRACK = new Set(["index", "search", "shared", "tracks"]);

const trackCache = new Map();

/**
 * The full phases for a track, from the lazily-loaded track file.
 *
 * Returns { status, phases, error } rather than throwing, because the caller is
 * a React component and every failure here should surface as a message on the
 * page rather than a blank screen.
 */
export async function loadTrackPhases(trackId) {
  if (trackCache.has(trackId)) {
    return { status: "ready", phases: trackCache.get(trackId), error: null };
  }
  if (NOT_A_TRACK.has(trackId)) {
    return { status: "error", phases: [], error: `${trackId} is not a track` };
  }

  const load = TRACK_MODULES[`./generated/${trackId}.json`];
  if (!load) {
    // A track with no authored phases emits no file at all. That is a normal
    // state (four tracks are still being written), not an error.
    return { status: "empty", phases: [], error: null };
  }

  try {
    const mod = await load();
    const data = mod.default || mod;
    const phases = (data.phases || []).map(normalisePhase);
    trackCache.set(trackId, phases);
    return { status: "ready", phases, error: null };
  } catch (e) {
    return { status: "error", phases: [], error: String((e && e.message) || e) };
  }
}

/** Synchronous accessor for a track already loaded. Null if not loaded yet. */
export function cachedTrackPhases(trackId) {
  return trackCache.has(trackId) ? trackCache.get(trackId) : null;
}

/**
 * The phases either side of this one, within its own track.
 *
 * Reads the light index rather than the full track, so paging through a track
 * never needs the phase bodies. Returns { prev, next } where either may be null
 * at a track boundary; PhaseNav renders whichever exist, so crossing a boundary
 * ends the sequence rather than wrapping into an unrelated track.
 */
export function neighbours(trackId, phaseId) {
  const track = findTrack(trackId);
  if (!track) return { prev: null, next: null };
  const i = track.phases.findIndex((p) => p.id === phaseId);
  if (i === -1) return { prev: null, next: null };
  return {
    prev: i > 0 ? track.phases[i - 1] : null,
    next: i < track.phases.length - 1 ? track.phases[i + 1] : null,
  };
}

/** The light index record for a phase, or null. */
export function findPhaseSummary(phaseId) {
  for (const t of tracks) {
    const p = t.phases.find((ph) => ph.id === phaseId);
    if (p) return { track: t, phase: p };
  }
  return null;
}

/**
 * The track id for a phase id, or null.
 *
 * WHY THIS EXISTS RATHER THAN USING THE SEARCH INDEX'S TRACK CODE
 * The search index stores a short track code per segment (`found`, `intern`,
 * `agent`), because it is built to be compact. Those codes are NOT track ids —
 * the ids are `foundations`, `model-internals`, `agents`. Passing the code
 * straight to a navigation handler produces a lookup that silently finds
 * nothing, which presents as a search result that does not open.
 *
 * Resolving from the phase id instead keeps one source of truth (the curriculum
 * index) and means the search index never has to carry anything but its own
 * compact keys. Phase ids are unique across the whole corpus, so this is
 * unambiguous.
 */
export function trackIdForPhase(phaseId) {
  const hit = findPhaseSummary(phaseId);
  return hit ? hit.track.id : null;
}

/** Every phase summary across every track, in curriculum order. */
export function allPhaseSummaries() {
  return tracks.flatMap((t) => t.phases.map((p) => ({ ...p, trackId: t.id })));
}

/** Totals, used by the dashboard header. Counted from the light index. */
export function corpusTotals() {
  const phases = allPhaseSummaries();
  return {
    tracks: tracks.length,
    tracksWithContent: tracks.filter((t) => t.phases.length > 0).length,
    phases: phases.length,
    lessonWords: phases.reduce((n, p) => n + (p.lessonWordCount || 0), 0),
    tasks: phases.reduce((n, p) => n + (p.taskIds || []).length, 0),
    checklist: phases.reduce((n, p) => n + (p.checklistIds || []).length, 0),
    quiz: phases.reduce((n, p) => n + (p.quizIds || []).length, 0),
  };
}
